<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {ArrowLeft,ArrowRight,ArrowUp,ArrowDown,Coins,Footprints,Pause,Play,Trophy,Volume2,VolumeX} from 'lucide-vue-next'
import DogSprite from './DogSprite.vue'
import RunnerScene from './RunnerScene.vue'
import {db,fail,friendly} from '../lib/supabase'
import {user} from '../lib/session'
import {newRunner,stepRunner,runScore,runnerKey,swipeAction,RUN_STEP,type RunAction} from '../lib/runner'
const props=defineProps<{disabled?:boolean;accessory?:string}>(),emit=defineEmits<{updated:[];active:[value:boolean]}>()
const shell=ref<HTMLElement|null>(null),field=ref<HTMLElement|null>(null),mode=ref<'menu'|'ready'|'playing'|'paused'|'result'>('menu')
const state=ref(newRunner(1)),busy=ref(false),error=ref(''),best=ref(0),ranking=ref<{alias:string;score:number}[]>([]),showRanks=ref(false)
const award=ref<{score:number;coins:number;xp:number;best:number;tokens:number}|null>(null)
let run:{id:string;seed:number}|null=null,inputs:number[]=[],queue:RunAction[]=[],lastInput=-10,raf=0,lastTime=0,accumulator=0,owner='',alive=true
let pointer:{id:number;x:number;y:number}|null=null
const sound=ref(false),coinTick=ref(-100),clearTick=ref(-100),crashKind=ref(0)
let audio:AudioContext|null=null
const score=computed(()=>runScore(state.value)),zone=computed(()=>['El jardín','El pueblo','Atardecer'][Math.min(2,Math.floor(state.value.tick/1200))]),pace=computed(()=>1+Math.min(5,Math.floor(state.value.tick/600)))
const pop=computed(()=>state.value.tick-coinTick.value<42?'¡Moneda!':state.value.tick-clearTick.value<28?'¡Bien esquivado!':'')
const crashTip=computed(()=>crashKind.value===1?'Salta las vallas: espacio, ↑ o un toque.':crashKind.value===2?'Pasa bajo los arcos: ↓ o desliza hacia abajo.':'Los setos se esquivan cambiando de carril.')
function tone(frequency:number){if(!sound.value)return;try{audio??=new AudioContext();void audio.resume();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.connect(gain);gain.connect(audio.destination);oscillator.frequency.value=frequency;gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);oscillator.start();oscillator.stop(audio.currentTime+.13)}catch{}}
function toggleSound(){sound.value=!sound.value;if(sound.value)tone(660)}
function focus(){field.value?.focus({preventScroll:true})}
async function records(){const id=user.value?.id;const {data,error:e}=await db.rpc('wedding_runner_records');if(!e&&alive&&id===user.value?.id){best.value=data.best;ranking.value=data.ranking}}
async function start(){if(busy.value||props.disabled||!user.value)return;busy.value=true;error.value='';owner=user.value.id
 try{const {data,error:e}=await db.rpc('wedding_runner_start');fail(e);if(!alive||owner!==user.value?.id)return;run=data;state.value=newRunner(data.seed);inputs=[];queue=[];lastInput=-10;coinTick.value=-100;clearTick.value=-100;crashKind.value=0;award.value=null;mode.value='ready';emit('active',true);emit('updated');await nextTick();shell.value?.scrollIntoView({block:'start',behavior:'instant'});focus()}catch(e){error.value=friendly(e)}finally{busy.value=false}
}
function schedule(){lastTime=performance.now();accumulator=0;raf=requestAnimationFrame(frame)}
function begin(){if(mode.value!=='ready')return;mode.value='playing';focus();schedule()}
function input(action:RunAction){if(!action)return;if(mode.value==='ready')begin();if(mode.value==='playing'&&queue.length<2){queue.push(action);focus()}}
function frame(time:number){if(mode.value!=='playing')return;const delta=time-lastTime;lastTime=time;if(delta>350){pause();return}accumulator+=delta
 while(accumulator>=RUN_STEP&&!state.value.dead){let action:RunAction=0;if(queue.length&&state.value.tick+1-lastInput>=4){action=queue.shift()!;lastInput=state.value.tick+1;inputs.push(lastInput*10+action)}const oldTokens=state.value.tokens,oldCleared=state.value.cleared,rows=[...state.value.rows];stepRunner(state.value,action);if(state.value.tokens>oldTokens){coinTick.value=state.value.tick;tone(880)}else if(state.value.cleared>oldCleared){clearTick.value=state.value.tick;tone(440)}if(state.value.dead&&state.value.tick<3600){crashKind.value=rows.find(r=>r.progress>=10000&&r.lane===state.value.lane)?.kind??3;tone(160)}accumulator-=RUN_STEP}
 if(state.value.dead){mode.value='result';void finish();return}raf=requestAnimationFrame(frame)
}
function pause(){if(mode.value!=='playing')return;cancelAnimationFrame(raf);queue=[];pointer=null;mode.value='paused'}
function resume(){mode.value='playing';focus();schedule()}
async function finish(){if(!run||busy.value||award.value)return;busy.value=true;error.value='';try{const {data,error:e}=await db.rpc('wedding_runner_finish',{run_id:run.id,inputs,ticks:state.value.tick});fail(e);if(!alive||owner!==user.value?.id)return;award.value=data;best.value=data.best;emit('updated');void records()}catch(e){if(alive)error.value=friendly(e)}finally{busy.value=false}}
function leave(){cancelAnimationFrame(raf);queue=[];pointer=null;mode.value='menu';run=null;emit('active',false)}
function key(e:KeyboardEvent){if(!['ready','playing','paused'].includes(mode.value)||e.ctrlKey||e.metaKey||e.altKey)return;const target=e.target as HTMLElement|null
 if(target?.isContentEditable||target?.closest('input,textarea,select,[role="dialog"]'))return
 if(target&&target!==document.body&&!shell.value?.contains(target))return
 if(['Escape','KeyP'].includes(e.code)){e.preventDefault();e.stopPropagation();if(!e.repeat){if(mode.value==='playing')pause();else if(mode.value==='paused')resume()}return}
 const action=runnerKey(e.code);if(action&&mode.value!=='paused'){e.preventDefault();e.stopPropagation();if(!e.repeat)input(action)}
}
function down(e:PointerEvent){if(mode.value!=='playing'||!e.isPrimary)return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY};field.value?.setPointerCapture(e.pointerId);focus()}
function up(e:PointerEvent){if(pointer?.id!==e.pointerId)return;const action=swipeAction(e.clientX-pointer.x,e.clientY-pointer.y);pointer=null;if(field.value?.hasPointerCapture(e.pointerId))field.value.releasePointerCapture(e.pointerId);input(action||3)}
function move(e:PointerEvent){if(pointer?.id!==e.pointerId)return;const action=swipeAction(e.clientX-pointer.x,e.clientY-pointer.y);if(action){pointer=null;input(action)}}
function hidden(){if(document.hidden)pause()}
watch(()=>user.value?.id,()=>{leave();award.value=null;best.value=0;ranking.value=[]})
onMounted(()=>{void records();window.addEventListener('keydown',key,true);document.addEventListener('visibilitychange',hidden);window.addEventListener('huellas-viewport-change',pause)})
onUnmounted(()=>{alive=false;cancelAnimationFrame(raf);void audio?.close();window.removeEventListener('keydown',key,true);document.removeEventListener('visibilitychange',hidden);window.removeEventListener('huellas-viewport-change',pause);emit('active',false)})
</script>
<template><section ref="shell" class="flappy-game runner-game" :class="{'runner-active':mode!=='menu'}"><template v-if="mode==='menu'"><button class="flappy-card runner-card" :disabled="disabled||busy" @click="start"><div class="flight-cover runner-cover"><span></span><DogSprite mood="playing"/><i>3 CARRILES</i></div><span><b>Huellas Surfer</b><small>Un paseo que se convierte en aventura.</small><em>{{busy?'Preparando…':'¡Vamos a correr! →'}}</em></span></button><div class="flight-record"><Trophy :size="16"/> Tu récord: {{best}} puntos <button @click="showRanks=!showRanks">Clasificación Surfer</button></div><p class="arcade-note">Esquiva, salta y deslízate. Recoge monedas para el armario.<br/>PC: flechas o WASD · Espacio: salto. Móvil: desliza o usa los botones.<br/>3 energía + 2 comida por partida · Hasta 60 s · Premios máximos: 60 monedas y 90 XP.</p><div v-if="showRanks" class="flappy-ranking"><p v-if="!ranking.length">Sé el primero. Activa la clasificación con alias desde tu perfil para aparecer.</p><ol v-else><li v-for="(r,i) in ranking" :key="i">{{r.alias}} <b>{{r.score}} puntos</b></li></ol></div><p v-if="error" class="pet-error" role="alert">{{error}}</p></template><template v-else><header class="flight-toolbar"><button v-if="mode==='result'" :disabled="busy" @click="leave" aria-label="Volver al patio desde Surfer"><ArrowLeft :size="20"/></button><Footprints v-else :size="21"/><b>Huellas Surfer<small>{{zone}}</small></b><span>{{Math.floor(state.tick/60)}} / 60 s</span><button @click="toggleSound" :aria-label="sound?'Desactivar sonido de Surfer':'Activar sonido de Surfer'"><Volume2 v-if="sound" :size="18"/><VolumeX v-else :size="18"/></button><button v-if="mode==='playing'" @click="pause" aria-label="Pausar Surfer"><Pause :size="20"/></button></header><div ref="field" class="flight-field runner-field" tabindex="0" role="application" aria-label="Huellas Surfer: izquierda y derecha para cambiar de carril, espacio o arriba para saltar, abajo para deslizarse." @pointerdown.prevent="down" @pointerup.prevent="up" @pointermove.prevent="move" @pointercancel="pointer=null"><RunnerScene :state="state" :running="mode==='playing'" :accessory="accessory"/>
<div class="surfer-hud"><div class="surfer-score"><small>PUNTOS</small><b>{{score.toLocaleString('es-ES')}}</b></div><div class="surfer-coins"><Coins :size="19"/><b>{{state.tokens}}</b></div></div>
<div class="surfer-progress"><span :style="{width:state.tick/36+'%'}"></span><i v-for="n in 2" :key="n" :style="{left:n*100/3+'%'}"></i></div>
<div v-if="mode==='playing'" class="surfer-pace"><span v-for="n in 6" :key="n" :class="{lit:n<=pace}"></span><b>RITMO {{pace}}</b></div>
<Transition name="surfer-pop"><div v-if="pop&&mode==='playing'" :key="coinTick+':'+clearTick" class="surfer-pop">{{pop}}</div></Transition>
<div v-if="mode==='playing'&&state.tick<240" class="surfer-tip">← → cambia · ↑ salta · ↓ desliza</div>
<div v-if="mode==='ready'" class="flight-overlay" @pointerdown.stop @pointerup.stop><div><span class="surfer-eyebrow">JARDÍN · PUEBLO · ATARDECER</span><h4>¡Las patitas al viento!</h4><p>Un minuto, tres carriles.<br/>¿Hasta dónde llegáis juntos?</p><div class="surfer-legend"><span><i class="mini-fence">↑</i>Salta</span><span><i class="mini-arch">↓</i>Desliza</span><span><i class="mini-hedge">↔</i>Esquiva</span></div><small class="runner-intro-controls">PC: ← → / A D · Espacio / ↑ salta · ↓ se agacha.<br/>Móvil: desliza o usa los botones.</small><button @click="begin">¡A correr!</button><button class="flight-secondary" @click="leave">Volver al patio</button></div></div><div v-else-if="mode==='paused'" class="flight-overlay" @pointerdown.stop @pointerup.stop><div><Pause :size="30"/><h4>Un respiro</h4><p>La carrera está en pausa.</p><button @click="resume"><Play :size="16"/> Seguir corriendo</button><button class="flight-secondary" @click="leave">Salir sin recompensa</button></div></div><div v-else-if="mode==='result'" class="flight-overlay" @pointerdown.stop @pointerup.stop><div><Trophy :size="30"/><h4>{{state.tick===3600?'¡Meta conseguida!':'¡Una vuelta más!'}}</h4><p class="result-score">{{score}} <small>puntos · {{state.tokens}} {{state.tokens===1?'moneda recogida':'monedas recogidas'}}</small></p><p v-if="busy" role="status">Guardando tu carrera…</p><div v-else-if="award" class="flight-prizes"><span><Coins :size="16"/> +{{award.coins}}</span><span>✦ +{{award.xp}} XP</span></div><p v-if="award">Tu récord: {{best}} puntos</p><p v-if="state.tick<3600" class="surfer-result-tip">{{crashTip}}</p><p v-if="error" class="flight-error" role="alert">{{error}}</p><button v-if="error&&!award" :disabled="busy" @click="finish">Reintentar guardar</button><button v-else :disabled="busy||disabled" @click="start">Otra carrera</button><button :disabled="busy" class="flight-secondary" @click="leave">Volver al patio</button></div></div></div><div class="runner-buttons" aria-label="Controles de Huellas Surfer"><button :disabled="mode!=='playing'" @click="input(1)" aria-label="Carril izquierdo"><ArrowLeft :size="20"/><span>Izquierda</span></button><button :disabled="mode!=='playing'" @click="input(3)" aria-label="Saltar"><ArrowUp :size="20"/><span>Saltar</span></button><button :disabled="mode!=='playing'" @click="input(4)" aria-label="Deslizarse"><ArrowDown :size="20"/><span>Deslizar</span></button><button :disabled="mode!=='playing'" @click="input(2)" aria-label="Carril derecho"><ArrowRight :size="20"/><span>Derecha</span></button></div><div class="game-controls-guide"><span><b>PC</b> <kbd>←</kbd> <kbd>→</kbd> carril · <kbd>Espacio</kbd> / <kbd>↑</kbd> salto · <kbd>↓</kbd> deslizar</span><span><kbd>P</kbd> / <kbd>Esc</kbd> pausa · También WASD.</span><span><b>Móvil</b> Desliza para moverte · Toca para saltar.</span></div></template></section></template>
